	}

	ut16 modref_count = bin->ne_header->ModRefs;
	ut16 *modref = NULL;
	if (modref_count > 0) {
		modref = calloc (modref_count, sizeof (ut16));
		if (!modref) {
			return NULL;
		}
		r_buf_read_at (bin->buf, (ut64)bin->ne_header->ModRefTable + bin->header_offset, (ut8 *)modref, modref_count * sizeof (ut16));
