	uint16_t offlg;
	long frag_len;

	dp = (const struct ip6_frag *)bp;
	ip6 = (const struct ip6_hdr *)bp2;

	ND_TCHECK(dp->ip6f_offlg);

	offlg = EXTRACT_16BITS(&dp->ip6f_offlg);
	frag_len = (long)sizeof(struct ip6_hdr) + (long)EXTRACT_16BITS(&ip6->ip6_plen) -
