		       EXTRACT_32BITS(&dp->ip6f_ident),
		       offlg & IP6F_OFF_MASK,
		       frag_len));
	} else {
		ND_PRINT((ndo, "frag (%d|%ld)",
		       offlg & IP6F_OFF_MASK,
		       frag_len));
