OMX_ERRORTYPE SimpleSoftOMXComponent::useBuffer(
        OMX_BUFFERHEADERTYPE **header,
        OMX_U32 portIndex,
        OMX_PTR appPrivate,
        OMX_U32 size,
        OMX_U8 *ptr) {

    Mutex::Autolock autoLock(mLock);

    if (header == NULL) {
        return OMX_ErrorBadParameter;
    }

    if (portIndex >= mPorts.size()) {
        return OMX_ErrorBadPortIndex;
    }

    PortInfo *port = &mPorts.editItemAt(portIndex);

    if (mState != OMX_StateLoaded && port->mDef.bEnabled != OMX_FALSE) {
        return OMX_ErrorIncorrectStateOperation;
    }

    if (port->mBuffers.size() >= port->mDef.nBufferCountActual) {
        return OMX_ErrorInsufficientResources;
    }

    OMX_BUFFERHEADERTYPE *newHeader = new (std::nothrow) OMX_BUFFERHEADERTYPE;
    if (newHeader == NULL) {
        return OMX_ErrorInsufficientResources;
    }

    newHeader->nSize = sizeof(OMX_BUFFERHEADERTYPE);
    newHeader->nVersion.s.nVersionMajor = 1;
    newHeader->nVersion.s.nVersionMinor = 0;
    newHeader->nVersion.s.nRevision = 0;
    newHeader->nVersion.s.nStep = 0;
    newHeader->pBuffer = ptr;
    newHeader->nAllocLen = size;
    newHeader->nFilledLen = 0;
    newHeader->nOffset = 0;
    newHeader->pAppPrivate = appPrivate;
    newHeader->pPlatformPrivate = NULL;
    newHeader->pInputPortPrivate = NULL;
    newHeader->pOutputPortPrivate = NULL;
    newHeader->hMarkTargetComponent = NULL;
    newHeader->pMarkData = NULL;
    newHeader->nTickCount = 0;
    newHeader->nTimeStamp = 0;
    newHeader->nFlags = 0;

    newHeader->nOutputPortIndex = portIndex;
    newHeader->nInputPortIndex = portIndex;

    port->mBuffers.push();

    BufferInfo *buffer =
        &port->mBuffers.editItemAt(port->mBuffers.size() - 1);

    buffer->mHeader = newHeader;
    buffer->mOwnedByUs = false;

    *header = newHeader;

    if (port->mBuffers.size() == port->mDef.nBufferCountActual) {
        port->mDef.bPopulated = OMX_TRUE;
        checkTransitions();
    }

    return OMX_ErrorNone;
}

