static irqreturn_t snd_msnd_interrupt(int irq, void *dev_id)
{
	struct snd_msnd *chip = dev_id;
	void *pwDSPQData = chip->mappedbase + DSPQ_DATA_BUFF;
	u16 wHead, wTail, wSize;

	/* Send ack to DSP */
	/* inb(chip->io + HP_RXL); */

	/* Evaluate queued DSP messages */
	wSize = readw(chip->DSPQ + JQS_wSize);
	wHead = readw(chip->DSPQ + JQS_wHead);
	wTail = readw(chip->DSPQ + JQS_wTail);
	while (wTail != wHead) {
		u16 wTmp;

		if (wHead > wSize)
			break;

		snd_msnd_eval_dsp_msg(chip,
			readw(pwDSPQData + 2 * wHead));

		wTmp = wHead + 1;
		if (wTmp > wSize)
			wTmp = 0;
		writew(wTmp, chip->DSPQ + JQS_wHead);
		wHead = wTmp;
		wTail = readw(chip->DSPQ + JQS_wTail);
	}
	/* Send ack to DSP */
	inb(chip->io + HP_RXL);
	return IRQ_HANDLED;
}

